// Tests for the PDF reader (pdf.js) and for feeding its table into import.js.
// No browser, no dependencies. Node 18+ (needs DecompressionStream).
//
//   node --test projects/chama-ledger/importer/test/pdf.test.cjs
//
// The encrypted fixture is generated by test/make-pdf-fixture.py. It is invented
// content with M-Pesa's real table geometry, password "chama".

const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");

const pdf = require("../pdf.js");
const importer = require("../import.js");

const fixturePath = path.join(__dirname, "fixtures", "mpesa-mini-encrypted.pdf");
const fixtureBytes = () => new Uint8Array(fs.readFileSync(fixturePath));
const PASSWORD = "chama";

/* ---------- primitives ---------- */

test("md5 matches the RFC 1321 vectors the key derivation relies on", () => {
  const vectors = [
    ["", "d41d8cd98f00b204e9800998ecf8427e"],
    ["abc", "900150983cd24fb0d6963f7d28e17f72"],
    ["message digest", "f96b697d7cb7938d525a2f31aaf161d0"],
    ["The quick brown fox jumps over the lazy dog", "9e107d9d372bb6826bd81d3542a419d6"],
  ];
  for (const [input, expected] of vectors) {
    const got = Buffer.from(pdf.md5(new Uint8Array(Buffer.from(input)))).toString("hex");
    assert.equal(got, expected, "md5(" + JSON.stringify(input) + ")");
  }
});

test("rc4 matches a published vector", () => {
  const got = Buffer.from(pdf.rc4(Buffer.from("Key"), Buffer.from("Plaintext")));
  assert.equal(got.toString("hex"), "bbf316e8d940af0ad3");
});

test("parseCMap reads bfchar and bfrange, and detects a two-byte codespace", () => {
  const cmap = [
    "/CIDInit /ProcSet findresource begin",
    "begincodespacerange",
    "<0000> <FFFF>",
    "endcodespacerange",
    "1 beginbfchar",
    "<0003> <0041>",
    "endbfchar",
    "1 beginbfrange",
    "<0010> <0012> <0061>",
    "endbfrange",
  ].join("\n");

  const parsed = pdf.parseCMap(cmap);
  assert.equal(parsed.twoByte, true);
  assert.equal(parsed.map["0003"], "A");
  assert.equal(parsed.map["0010"], "a");
  assert.equal(parsed.map["0012"], "c");
});

/* ---------- layout ---------- */

test("bandize groups items on the same baseline and orders them left to right", () => {
  const bands = pdf.bandize([
    { page: 0, x: 300, y: 500, text: "right" },
    { page: 0, x: 40, y: 501, text: "left" },
    { page: 0, x: 40, y: 480, text: "below" },
  ]);

  assert.equal(bands.length, 2);
  assert.deepEqual(bands[0].items.map((i) => i.text), ["left", "right"]);
  assert.deepEqual(bands[1].items.map((i) => i.text), ["below"]);
});

test("rowsFromItems anchors on the date, keeps wrapped Details, and reads the amount sign", () => {
  const items = [
    { page: 0, x: 51, y: 560, text: "Receipt No." },
    { page: 0, x: 111, y: 560, text: "Completion Time" },
    { page: 0, x: 282, y: 560, text: "Transaction Status" },
    { page: 0, x: 510, y: 560, text: "Balance" },

    { page: 0, x: 38, y: 548, text: "AAA0000001" },
    { page: 0, x: 108, y: 548, text: "2026-11-02 09:15:00" },
    { page: 0, x: 178, y: 548, text: "Funds received from -" },
    { page: 0, x: 282, y: 548, text: "Completed" },
    { page: 0, x: 400, y: 548, text: "2,000.00" },
    { page: 0, x: 510, y: 548, text: "12,000.00" },
    { page: 0, x: 178, y: 542, text: "MARY WANJIKU" },

    { page: 0, x: 38, y: 530, text: "AAA0000002" },
    { page: 0, x: 108, y: 530, text: "2026-11-03 10:00:00" },
    { page: 0, x: 178, y: 530, text: "Pay Bill Online to 400200 -" },
    { page: 0, x: 282, y: 530, text: "Completed" },
    { page: 0, x: 465, y: 530, text: "-500.00" },
    { page: 0, x: 510, y: 530, text: "11,500.00" },
    { page: 0, x: 178, y: 524, text: "KPLC PREPAID" },
    { page: 0, x: 38, y: 496, text: "Disclaimer: personal information" },
  ];

  const warnings = [];
  const rows = pdf.rowsFromItems(items, warnings);

  assert.equal(rows.length, 2);
  assert.equal(warnings.length, 0);

  assert.equal(rows[0].receipt, "AAA0000001");
  assert.equal(rows[0].status, "COMPLETE");
  assert.equal(rows[0].amount, "2,000.00");
  assert.equal(rows[0].balance, "12,000.00");
  assert.deepEqual(rows[0].extra, ["MARY WANJIKU"]);

  assert.equal(rows[1].amount, "-500.00");
  assert.deepEqual(rows[1].extra, ["KPLC PREPAID"]);
});

/* ---------- the encrypted fixture ---------- */

test("an encrypted PDF without the password fails with BAD_PASSWORD", async () => {
  await assert.rejects(
    () => pdf.extractTable(fixtureBytes(), ""),
    (err) => err.code === "BAD_PASSWORD"
  );
});

test("a wrong password fails with BAD_PASSWORD", async () => {
  await assert.rejects(
    () => pdf.extractTable(fixtureBytes(), "not-the-password"),
    (err) => err.code === "BAD_PASSWORD"
  );
});

test("a file that is not a PDF fails with NOT_PDF", async () => {
  await assert.rejects(
    () => pdf.extractTable(new Uint8Array(Buffer.from("Receipt No.,Details\n")), ""),
    (err) => err.code === "NOT_PDF"
  );
});

test("the encrypted fixture decrypts into the same table the CSV path expects", async () => {
  const table = await pdf.extractTable(fixtureBytes(), PASSWORD);

  assert.equal(table.pageCount, 2);
  assert.equal(table.rows.length, 3);
  assert.deepEqual(table.warnings, []);
  assert.deepEqual(table.headers, [
    "Receipt No.", "Completion Time", "Details", "Transaction Status",
    "Paid In", "Withdrawn", "Balance",
  ]);

  const byReceipt = Object.fromEntries(table.rows.map((row) => [row[0], row]));

  assert.equal(byReceipt.AAA0000001[1], "2026-11-02 09:15:00");
  assert.equal(byReceipt.AAA0000001[2], "Funds received from - 254700***001 MARY WANJIKU");
  assert.equal(byReceipt.AAA0000001[3], "COMPLETE");
  assert.equal(byReceipt.AAA0000001[4], "2000.00");
  assert.equal(byReceipt.AAA0000001[5], "");
  assert.equal(byReceipt.AAA0000001[6], "12,000.00");

  assert.equal(byReceipt.AAA0000002[2], "Pay Bill Online to 400200 - KPLC PREPAID Acc. 12345678");
  assert.equal(byReceipt.AAA0000002[4], "");
  assert.equal(byReceipt.AAA0000002[5], "500.00");

  assert.equal(byReceipt.AAA0000003[2], "Customer Transfer of Funds Charge");
  assert.equal(byReceipt.AAA0000003[5], "23.00");

  const sum = (index) => table.rows.reduce((total, row) => total + Number(row[index].replace(/,/g, "") || 0), 0);
  assert.equal(sum(4).toFixed(2), "2000.00");
  assert.equal(sum(5).toFixed(2), "523.00");

  for (const row of table.rows) {
    assert.match(row[0], /^[A-Z0-9]{9,12}$/);
    assert.match(row[1], /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/);
    assert.equal(row[3], "COMPLETE");
  }
});

/* ---------- import.js accepts a table ---------- */

test("parseTable trims a table but leaves CSV parsing alone", () => {
  const table = importer.parseTable({
    headers: [" Receipt No. ", "Details"],
    rows: [[" A1 ", " Funds from MARY "], [" A2 "]],
  });

  assert.deepEqual(table.headers, ["Receipt No.", "Details"]);
  assert.deepEqual(table.rows, [["A1", "Funds from MARY"], ["A2"]]);
  assert.deepEqual(importer.parseTable("a,b\n1,2\n"), importer.parseCsv("a,b\n1,2\n"));
});

test("building from a parsed table gives exactly the same statement as the CSV text", () => {
  const csv = fs.readFileSync(path.join(__dirname, "..", "fixtures", "mpesa-clean.csv"), "utf8");
  const group = JSON.parse(fs.readFileSync(path.join(__dirname, "..", "fixtures", "group-clean.json"), "utf8"));

  const fromCsv = importer.buildStatement(group, csv);
  const fromTable = importer.buildStatement(group, importer.parseCsv(csv));

  assert.deepEqual(fromTable.statement, fromCsv.statement);
  assert.deepEqual(fromTable.report.matched, fromCsv.report.matched);
});

test("a PDF flows all the way to a member statement", async () => {
  const table = await pdf.extractTable(fixtureBytes(), PASSWORD);

  const group = {
    group: "Test Chama",
    period: "November 2026",
    periodStart: "2026-11-01",
    periodEnd: "2026-11-30",
    openingBalance: 11477,
    statementBalances: { mpesa: 11477, cash: 0 },
    members: [
      { name: "MARY WANJIKU", phone: "254700000001", expected: 2000, note: "" },
      { name: "JOHN KAMAU", phone: "254700000002", expected: 2000, note: "" },
    ],
    loans: [],
    expenses: [],
    fines: [],
    socialFund: [],
  };

  const { statement, report } = importer.buildStatement(group, table);

  assert.deepEqual(report.mapping, {
    receipt: 0, date: 1, details: 2, status: 3, paidIn: 4, withdrawn: 5,
  });

  assert.equal(report.totalTransactions, 3);
  assert.equal(report.inflows, 1);
  assert.equal(report.outflows.length, 2);
  assert.equal(report.matched.length, 1);
  assert.equal(report.matched[0].member, "MARY WANJIKU");
  assert.equal(report.matched[0].amount, 2000);

  const mary = statement.members.find((m) => m.name === "MARY WANJIKU");
  assert.equal(mary.paid, 2000);
  assert.equal(mary.ref, "AAA0000001");
  assert.equal(mary.date, "2026-11-02");

  const serialised = JSON.stringify(statement);
  assert.equal(serialised.includes("254700000001"), false, "a phone number reached the statement");
  assert.equal(serialised.includes("254700***001"), false, "the raw Details line reached the statement");
});
